package com.dating.backend.matching;
import com.dating.backend.entity.*;import com.dating.backend.admin.*;import jakarta.persistence.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.web.server.ResponseStatusException;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class ServiceSupportTest {
 @Autowired EntityManager em;@Autowired CompensationService compensation;@Autowired ReportConversationService conversations;
 User a,b,c;
 @BeforeEach void setup(){a=person();b=person();c=person();role("OWNER");}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 User person(){var u=User.builder().email(UUID.randomUUID()+"@test.local").nickname(UUID.randomUUID().toString().substring(0,12)).provider("LOCAL").status("ACTIVE").build();em.persist(u);return u;}
 void role(String role){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new AdminService.Principal(99L,"test-admin",role,"csrf"),null,List.of()));}
 @Test void grantRetriesExactlyOnceAndMessageIsDelivered(){var r=new CompensationService.Grant(30,"서비스 보상 안내",UUID.randomUUID().toString());var first=compensation.grant(a.getId(),r);assertEquals(first,compensation.grant(a.getId(),r));assertEquals(30,em.find(CreditWallet.class,a.getId()).getBalance());assertEquals(1,em.createQuery("select count(n) from AppNotice n where n.userId=:u",Long.class).setParameter("u",a.getId()).getSingleResult());assertEquals("서비스 보상 안내",em.find(CreditEntry.class,first.entryId()).getMessage());assertThrows(ResponseStatusException.class,()->compensation.grant(a.getId(),new CompensationService.Grant(31,r.message(),r.requestId())));}
 @Test void grantRejectsUnauthorizedAndInvalidAmount(){role("READ_ONLY");assertThrows(ResponseStatusException.class,()->compensation.grant(a.getId(),new CompensationService.Grant(10,"test",UUID.randomUUID().toString())));role("SUPPORT");assertThrows(ResponseStatusException.class,()->compensation.grant(a.getId(),new CompensationService.Grant(-10,"test",UUID.randomUUID().toString())));assertEquals(10,compensation.grant(a.getId(),new CompensationService.Grant(10,"test",UUID.randomUUID().toString())).balance());}
 @Test void evidenceRejectsOtherRoomAndOwnMessageAndKeepsContext(){var room=new ChatRoom();room.setLowId(Math.min(a.getId(),b.getId()));room.setHighId(Math.max(a.getId(),b.getId()));em.persist(room);var own=message(room,a);var peer=message(room,b);assertThrows(ResponseStatusException.class,()->conversations.validate(a.getId(),b.getId(),List.of(own.getId())));assertThrows(ResponseStatusException.class,()->conversations.validate(c.getId(),b.getId(),List.of(peer.getId())));String ids=conversations.validate(a.getId(),b.getId(),List.of(peer.getId()));var report=UserReport.builder().reporterUserId(a.getId()).reportedUserId(b.getId()).reasonCode("OTHER").detail("test").selectedMessageIds(ids).build();em.persist(report);var lines=conversations.view(report.getId());assertEquals(2,lines.size());assertEquals(1,lines.stream().filter(ReportConversationService.Line::selected).count());role("READ_ONLY");assertThrows(ResponseStatusException.class,()->conversations.view(report.getId()));}
 ChatMessage message(ChatRoom r,User u){var m=new ChatMessage();m.setRoomId(r.getId());m.setSenderId(u.getId());m.setClientId(UUID.randomUUID().toString());m.setBody("message");em.persist(m);return m;}
 @Test void adminRoutesProtectGrantsAndEvidence(){assertFalse(AdminFilter.allowed("REVIEWER","POST","/api/admin/console/members/1/compensation"));assertTrue(AdminFilter.allowed("SUPPORT","POST","/api/admin/console/members/1/compensation"));assertFalse(AdminFilter.allowed("READ_ONLY","GET","/api/admin/safety/reports/1/conversation"));}
}
